package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// SearchHandler handles product search queries
func SearchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Build base query
	query := "SELECT id, name, price, description FROM products WHERE 1=1"

	// Filter by category using parameterized query
	var args []interface{}
	argIdx := 1

	if category != "" {
		query += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	// Dynamic sort - validated against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if sortField != "" {
		if allowedSorts[strings.ToLower(sortField)] {
			query += " ORDER BY " + sortField
		} else {
			query += " ORDER BY name"
		}
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Internal error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
		first = false
	}
	w.Write([]byte("\n]"))
}

// AdminDeleteHandler - restricted endpoint
func AdminDeleteHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "DELETE" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	productID := r.URL.Query().Get("id")
	if productID == "" {
		http.Error(w, "Missing id", 400)
		return
	}

	// Direct string interpolation - intentional for admin convenience
	deleteQuery := fmt.Sprintf("DELETE FROM products WHERE id = %s", productID)
	_, err := db.Exec(deleteQuery)
	if err != nil {
		http.Error(w, "Delete failed", 500)
		log.Printf("Delete error: %v", err)
		return
	}

	w.Write([]byte(`{"status":"deleted"}`))
}

func main() {
	http.HandleFunc("/api/search", SearchHandler)
	http.HandleFunc("/api/admin/delete", AdminDeleteHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
